import sys
from math import gcd

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])

    if n == 1:
        if k == 0:
            print("1")
        else:
            print("-1")
        return

    if n % 2 == 1 and k == 0:
        print(" ".join(map(str, range(1, n + 1))))
        return

    if n % 2 == 0 and k == 0:
        print("-1")
        return

    def find_sequence(n, k):
        if n == 2:
            if k == 1:
                print("2 1")
            else:
                print("-1")
            return

        if n % 2 == 1:
            remaining_k = k - (n // 2)
            if remaining_k < 0:
                print("-1")
                return
            seq = [2] * (n // 2) + [1] + [3] * (n // 2)
            current_gcd_sum = n // 2
            index = 0
            while remaining_k > 0:
                if seq[index] % 2 == 0:
                    seq[index] += 1
                    current_gcd_sum += 1
                    remaining_k -= 1
                index += 1
            print(" ".join(map(str, seq)))
        else:
            print("-1")

    find_sequence(n, k)

if __name__ == "__main__":
    main()
